const tools=document.createElement('div');tools.className='replay-tools';tools.innerHTML='<button id="restart-run">↺ Restart</button><button id="jump-quarter">+25% timeline →</button><button id="focus-scene" aria-pressed="false">⛶ Focus workcell</button><a href="analytics.html">Compare analytics ↗</a>';document.querySelector('.run-toolbar').after(tools);const replayVideo=document.querySelector('#main-video');document.querySelector('#restart-run').onclick=()=>{replayVideo.pause();replayVideo.currentTime=0};document.querySelector('#jump-quarter').onclick=()=>{if(Number.isFinite(replayVideo.duration))replayVideo.currentTime=Math.min(replayVideo.duration,replayVideo.currentTime+replayVideo.duration/4)};document.querySelector('#focus-scene').onclick=e=>{const active=document.body.classList.toggle('focus-scene');e.currentTarget.setAttribute('aria-pressed',active);e.currentTarget.textContent=active?'↙ Exit focus':'⛶ Focus workcell'};
